":\"Shiny Radar\",\"homeNote\":\"Današnji serveri i vjerojatni ciklus.\",\"confirmed\":\"Bot potvrđeno\",\"waiting\":\"Čekanje snimki Bota\",\"probable\":\"Vjerojatni ciklus\",\"today\":\"Danas\",\"latest\":\"Zadnja potvrda\",\"local\":\"Server 1591\",\"localDays\":\"Shiny utorkom i subotom\",\"excluded\":\"1591 ostaje izvan vanjskih popisa\",\"refresh\":\"Shiny sažetak\",\"full\":\"Puni Radar\",\"group\":\"Grupa\",\"servers\":\"servera\"},\"pt\":{\"nav\":\"Shiny Radar\",\"home\":\"Shiny Radar\",\"homeNote\":\"Servidores de hoje e ciclo provável.\",\"confirmed\":\"Confirmados pelo Bot\",\"waiting\":\"À espera das capturas do Bot\",\"probable\":\"Ciclo provável\",\"today\":\"Hoje\",\"latest\":\"Última confirmação\",\"local\":\"Servidor 1591\",\"localDays\":\"Shiny terça e sábado\",\"excluded\":\"1591 continua excluído das listas externas\",\"refresh\":\"Resumo shiny\",\"full\":\"Radar completo\",\"group\":\"Grupo\",\"servers\":\"servidores\"}}\n  };\n\n  const OWNER_KEY = 'gomo-central-shiny-owner';\n  const qs = new URLSearchParams(location.search);\n  if (qs.get('gomoShinyOwner') === SHINY.ownerToken) {\n    localStorage.setItem(OWNER_KEY, '1');\n    qs.delete('gomoShinyOwner');\n    const clean = location.pathname + (qs.toString() ? '?' + qs.toString() : '') + (location.hash || '#shiny');\n    history.replaceState(null, '', clean);\n  }\n\n  const lang = () => ((typeof currentLanguage !== 'undefined' && currentLanguage) || localStorage.getItem('gomo-central-language') || 'fr');\n  const t = () => SHINY.tx[lang()] || SHINY.tx.fr;\n  const esc = (v) => String(v ?? '').replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n\n  function brusselsYmd(date = new Date()) {\n    const parts = new Intl.DateTimeFormat('en-CA', {timeZone:'Europe/Brussels',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date);\n    const m = Object.fromEntries(parts.map(p => [p.type,p.value]));\n    return `${m.year}-${m.month}-${m.day}`;\n  }\n  function parseYmd(s) { const [y,m,d]=s.split('-').map(Number); return Date.UTC(y,m-1,d); }\n  function diffDays(a,b) { return Math.round((parseYmd(a)-parseYmd(b))/86400000); }\n  function predictedGroup(dateStr) {\n    const diff = diffDays(dateStr, SHINY.anchorDate);\n    const idx = ((SHINY.anchorIndex + diff) % SHINY.rotation.length + SHINY.rotation.length) % SHINY.rotation.length;\n    return SHINY.rotation[idx];\n  }\n  function formatDate(s) { const [y,m,d]=s.split('-'); return `${d}/${m}/${y}`; }\n  function chips(list, cls) { return list.map(n => `<span class=\"shiny-chip ${cls}\">${esc(n)}</span>`).join(''); }\n\n  function addStyles() {\n    if (document.getElementById('gomo-shiny-style')) return;\n    const style = document.createElement('style');\n    style.id = 'gomo-shiny-style';\n    style.textContent = `\n      .shiny-home-card{border-color:rgba(243,190,45,.48)!important;background:linear-gradient(135deg,rgba(28,21,8,.96),rgba(10,24,40,.96))!important}\n      .shiny-home-icon{width:66px;height:66px;border-radius:16px;display:grid;place-items:center;background:radial-gradient(circle at 50% 42%,#3b300d,#0a1524 74%);border:1px solid rgba(246,198,62,.45);font-size:34px;box-shadow:0 0 22px rgba(246,190,31,.16)}\n      .shiny-shell{max-width:940px;margin:0 auto}\n      .shiny-hero{position:relative;overflow:hidden;border:1px solid rgba(244,186,30,.78);border-radius:26px;min-height:420px;background:#07101c center/cover no-repeat;box-shadow:0 22px 55px rgba(0,0,0,.38),0 0 30px rgba(235,173,19,.08) inset}\n      .shiny-hero::after{content:'';position:absolute;inset:0;background:linear-gradient(180deg,transparent 62%,rgba(5,12,21,.92));pointer-events:none}\n      .shiny-hero-badge{position:absolute;left:22px;bottom:18px;z-index:2;padding:8px 12px;border-radius:999px;border:1px solid rgba(91,186,255,.28);background:rgba(5,15,26,.76);color:#75c9ff;font-weight:800}\n      .shiny-panel{position:relative;margin-top:-18px;z-index:3;border:1px solid rgba(244,186,30,.62);border-radius:24px;background:linear-gradient(180deg,#0a1726,#07111e);padding:22px;box-shadow:0 20px 45px rgba(0,0,0,.35)}\n      .shiny-top-grid{display:grid;grid-template-columns:220px minmax(0,1fr);gap:20px;align-items:stretch}\n      .shiny-compass{border:1px solid rgba(243,190,45,.58);border-radius:20px;background:#07121f;overflow:hidden;min-height:220px;display:grid;place-items:center;box-shadow:0 0 24px rgba(236,179,33,.12)}\n      .shiny-compass img{width:100%;height:100%;object-fit:cover;display:block}\n      .shiny-statuses{display:grid;gap:12px}\n      .shiny-block{padding:16px;border:1px solid rgba(255,255,255,.09);border-radius:18px;background:rgba(255,255,255,.025)}\n      .shiny-title-row{display:flex;align-items:center;gap:10px;margin-bottom:11px}\n      .shiny-dot{width:13px;height:13px;border-radius:50%;box-shadow:0 0 13px currentColor}\n      .shiny-dot.green{background:#44e028;color:#44e028} .shiny-dot.gold{background:#ffc121;color:#ffc121}\n      .shiny-title-row strong{font-size:18px}\n      .shiny-note{color:#9fb0c4;line-height:1.45;margin:0}\n      .shiny-chips{display:flex;gap:8px;flex-wrap:wrap}\n      .shiny-chip{display:inline-flex;align-items:center;justify-content:center;min-width:58px;padding:7px 10px;border-radius:999px;font-weight:850;font-variant-numeric:tabular-nums}\n      .shiny-chip.confirmed{color:#e8ffd7;border:1px solid rgba(82,255,65,.48);background:linear-gradient(180deg,rgba(22,89,20,.74),rgba(5,48,17,.82));box-shadow:0 0 10px rgba(55,255,44,.10)}\n      .shiny-chip.probable{color:#ffe8a2;border:1px solid rgba(255,194,30,.62);background:linear-gradient(180deg,rgba(107,74,0,.70),rgba(51,35,0,.82));box-shadow:0 0 10px rgba(255,190,25,.10)}\n      .shiny-meta{display:grid;gap:0;margin-top:16px;border-top:1px solid rgba(255,255,255,.08)}\n      .shiny-meta-row{display:grid;grid-template-columns:180px minmax(0,1fr);gap:16px;padding:13px 3px;border-bottom:1px solid rgba(255,255,255,.08)}\n      .shiny-meta-row span:first-child{color:#dbe5ef} .shiny-meta-row strong{color:#6ebdff}\n      .shiny-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:17px}\n      .shiny-refresh{flex:1;min-width:220px;border:1px solid rgba(255,193,31,.75);border-radius:15px;padding:14px 18px;background:linear-gradient(180deg,#17263b,#0b1727);color:#f5c54e;font-weight:900;font-size:18px;box-shadow:0 0 18px rgba(255,190,31,.14)}\n      .shiny-owner{border:1px solid rgba(116,199,255,.38);border-radius:15px;padding:14px 18px;background:#0b1c30;color:#8bd2ff;font-weight:850}\n      .shiny-source{text-align:center;color:#6ebdff;font-size:12px;margin:14px 0 0}\n      @media(max-width:700px){\n        .shiny-hero{min-height:360px;border-radius:21px;background-position:center top}\n        .shiny-hero-badge{left:14px;bottom:14px;font-size:12px}\n        .shiny-panel{padding:14px;border-radius:20px}\n        .shiny-top-grid{grid-template-columns:115px minmax(0,1fr);gap:12px}\n        .shiny-compass{min-height:170px;border-radius:16px}\n        .shiny-title-row strong{font-size:16px}\n        .shiny-chip{min-width:52px;padding:6px 8px;font-size:13px}\n        .shiny-meta-row{grid-template-columns:1fr;gap:4px;padding:11px 2px}\n      }\n    `;\n    document.head.appendChild(style);\n  }\n\n  function addUi() {\n    addStyles();\n    if (!document.getElementById('shiny')) {\n      const nav = document.querySelector('.main-nav');\n      if (nav) {\n        const btn = document.createElement('button');\n        btn.className='nav-item'; btn.type='button'; btn.dataset.page='shiny';\n        btn.innerHTML='✨ <span data-shiny-nav></span>';\n        const train = nav.querySelector('[data-page=\"train\"]');\n        if (train) nav.insertBefore(btn, train); else nav.appendChild(btn);\n      }\n      const main=document.querySelector('main.content');\n      if (main) {\n        const sec=document.createElement('section'); sec.id='shiny'; sec.className='page';\n        sec.innerHTML=`<div class=\"shiny-shell\"><div class=\"page-header\"><span class=\"eyebrow\">GOMO CENTRAL</span><h1>Shiny Radar</h1></div><article class=\"shiny-hero\" id=\"shinyHero\"><div class=\"shiny-hero-badge\">✨ Serveurs shiny du jour</div></article><section class=\"shiny-panel\"><div class=\"shiny-top-grid\"><div class=\"shiny-compass\"><img id=\"shinyCompass\" alt=\"Boussole dorée Shiny\"></div><div class=\"shiny-statuses\"><div class=\"shiny-block\"><div class=\"shiny-title-row\"><span class=\"shiny-dot green\"></span><strong id=\"shinyConfirmedTitle\"></strong></div><div id=\"shinyConfirmed\"></div></div><div class=\"shiny-block\"><div class=\"shiny-title-row\"><span class=\"shiny-dot gold\"></span><strong id=\"shinyProbableTitle\"></strong></div><div id=\"shinyProbable\"></div></div></div></div><div class=\"shiny-meta\"><div class=\"shiny-meta-row\"><span id=\"shinyTodayLabel\"></span><strong id=\"shinyToday\"></strong></div><div class=\"shiny-meta-row\"><span id=\"shinyLatestLabel\"></span><strong id=\"shinyLatest\"></strong></div><div class=\"shiny-meta-row\"><span id=\"shinyLocalLabel\"></span><strong id=\"shinyLocal\"></strong></div></div><div class=\"shiny-actions\"><button id=\"shinyRefresh\" class=\"shiny-refresh\" type=\"button\"></button><a id=\"shinyOwner\" class=\"shiny-owner hidden\" target=\"_blank\" rel=\"noopener\"></a></div><p id=\"shinySource\" class=\"shiny-source\"></p></section></div>`;\n        main.appendChild(sec);\n      }\n      const grid=document.querySelector('#home .action-grid');\n      if (grid && !document.getElementById('shinyHomeCard')) {\n        const card=document.createElement('button');\n        card.id='shinyHomeCard'; card.type='button'; card.className='action-card shiny-home-card'; card.dataset.go='shiny';\n        card.innerHTML='<span class=\"shiny-home-icon\">📡</span><span><strong data-shiny-home-title></strong><small data-shiny-home-note></small></span>';\n        grid.appendChild(card);\n      }\n    }\n    const hero=document.getElementById('shinyHero'); if(hero) hero.style.backgroundImage=`url(\"${SHINY.hero}\")`;\n    const compass=document.getElementById('shinyCompass'); if(compass) compass.src=SHINY.compass;\n    const owner=document.getElementById('shinyOwner');\n    if(owner) { owner.href=SHINY.radarUrl; owner.classList.toggle('hidden',localStorage.getItem(OWNER_KEY)!=='1'); }\n    document.getElementById('shinyRefresh')?.addEventListener('click', render);\n    document.querySelector('[data-page=\"shiny\"]')?.addEventListener('click',()=>setTimeout(render,0));\n    renderText(); render();\n  }\n\n  function renderText() {\n    const x=t();\n    document.querySelectorAll('[data-shiny-nav]').forEach(el=>el.textContent=x.nav);\n    document.querySelectorAll('[data-shiny-home-title]').forEach(el=>el.textContent=x.home);\n    document.querySelectorAll('[data-shiny-home-note]').forEach(el=>el.textContent=x.homeNote);\n    const set=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=v;};\n    set('shinyConfirmedTitle',x.confirmed); set('shinyProbableTitle',x.probable);\n    set('shinyTodayLabel',x.today); set('shinyLatestLabel',x.latest); set('shinyLocalLabel',x.local);\n    set('shinyRefresh',x.refresh); set('shinyOwner',x.full);\n  }\n\n  function render() {\n    renderText();\n    const x=t(); const today=brusselsYmd(); const pred=predictedGroup(today); const conf=SHINY.confirmed[today];\n    const cbox=document.getElementById('shinyConfirmed'); const pbox=document.getElementById('shinyProbable');\n    if(cbox) {\n      if(conf) cbox.innerHTML=`<div class=\"shiny-chips\">${chips(SHINY.groups[conf]||[],'confirmed')}</div><p class=\"shiny-note\" style=\"margin-top:9px\">${esc(x.group)} ${esc(conf)} • ${(SHINY.groups[conf]||[]).length} ${esc(x.servers)}</p>`;\n      else cbox.innerHTML=`<p class=\"shiny-note\">${esc(x.waiting)}</p>`;\n    }\n    if(pbox) {\n      if(conf) pbox.innerHTML=`<p class=\"shiny-note\">${esc(x.group)} ${esc(pred)} — cycle confirmé aujourd’hui.</p>`;\n      else pbox.innerHTML=`<div class=\"shiny-chips\">${chips(SHINY.groups[pred]||[],'probable')}</div><p class=\"shiny-note\" style=\"margin-top:9px\">${esc(x.group)} ${esc(pred)} • ${(SHINY.groups[pred]||[]).length} ${esc(x.servers)}</p>`;\n    }\n    const todayEl=document.getElementById('shinyToday'); if(todayEl) todayEl.textContent=`${formatDate(today)} • ${x.group} ${conf||pred}${conf?' ✓':' (probable)'}`;\n    const latest=document.getElementById('shinyLatest'); if(latest) latest.textContent=`${formatDate(SHINY.latestConfirmed)} • ${x.group} ${SHINY.confirmed[SHINY.latestConfirmed]||'?'}`;\n    const local=document.getElementById('shinyLocal'); if(local) local.textContent=`${x.localDays} • ${x.excluded}`;\n    const src=document.getElementById('shinySource'); if(src) src.textContent=`13 journées Bot confirmées • rotation observée A → C → B`;\n  }\n\n  const oldTranslate = typeof translatePage === 'function' ? translatePage : null;\n  if(oldTranslate && !window.__gomoShinyTranslateWrapped) {\n    window.__gomoShinyTranslateWrapped=true;\n    const wrapped=function(...args){ const r=oldTranslate.apply(this,args); setTimeout(()=>{renderText();render();},0); return r; };\n    try { translatePage = wrapped; } catch {}\n  }\n\n  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',addUi,{once:true}); else addUi();\n  window.addEventListener('pageshow',()=>{addUi();render();});\n  window.addEventListener('hashchange',()=>{if(location.hash==='#shiny')setTimeout(render,0);});\n})();";

export default {
  async fetch(request, env, ctx) {
    const response = await baseWorker.fetch(request, env, ctx);
    if (!response) return response;

    const url = new URL(request.url);
    const headers = new Headers(response.headers);
    headers.set("x-gomo-central-version", "1.9");

    if (url.pathname === "/assets/app-v1.5.js" && response.ok) {
      const source = await response.text();
      headers.delete("content-length");
      headers.delete("etag");
      headers.set("content-type", "application/javascript; charset=utf-8");
      headers.set("cache-control", "no-store");
      return new Response(`${source}\n${SHINY_PATCH}`, {
        status: response.status,
        statusText: response.statusText,
        headers
      });
    }

    return new Response(response.body, {
      status: response.status,
      statusText: response.statusText,
      headers
    });
  }
};
